<script lang="ts">
 import { untrack } from 'svelte';
 import { enhance } from '$app/forms';
 import { ArrowUpRight, ArrowRight, Phone, DoorOpen, KeyRound, Wrench, Building2, House, Clock, MapPin, Camera } from 'lucide-svelte';
 import type { PageData, ActionData } from '../../../routes/carlzipf/public/$types';
 let { data, form }: { data: PageData; form: ActionData } = $props();
 let sending = $state(false);
 let requestMode = $state(untrack(() => form?.values?.requestMode ?? 'assessment'));
 $effect(() => { if (form?.values?.requestMode) requestMode = form.values.requestMode; });
 const serviceOptions = [
  { value: 'replacement', title: 'Doors & frames', detail: 'Find the right fit for a new or replacement door.', icon: DoorOpen },
  { value: 'hardware', title: 'Locks & hardware', detail: 'Make every entrance work the way it should.', icon: KeyRound },
  { value: 'repair', title: 'Door & lock repairs', detail: 'Get sticking doors and troublesome locks working again.', icon: Wrench },
  { value: 'rekey', title: 'Rekeying', detail: 'A fresh start for who has access to your property.', icon: KeyRound }
 ];
</script>



