  <nav aria-label="Main navigation"><a href="/carlzipf/portal/login">{data.content.residentialText.copy_4}</a><a href="#services">{data.content.residentialText.copy_5}</a><a href="#visit">{data.content.residentialText.copy_6}</a><a class="button small" href="#request">{data.content.residentialText.copy_7}<ArrowUpRight size={17} /></a></nav>
